<?php
namespace App\Livewire\Biometric;
use App\Models\BiometricDevice; use App\Models\BiometricEmployeeMapping; use App\Models\Employee; use App\Services\BiometricDeviceService; use Livewire\Component;
class Devices extends Component { public string $name='';public string $timezone='Asia/Amman';public ?int $deviceId=null;public ?int $employeeId=null;public string $externalEmployeeId='';public ?string $newToken=null;public function create(BiometricDeviceService $s):void{$this->authorize('manage-hr');$d=$this->validate(['name'=>'required|string|max:255','timezone'=>'required|timezone']);$r=$s->create($d['name'],$d['timezone']);$this->newToken=$r['token'];$this->reset('name');} public function map(BiometricDeviceService $s):void{$this->authorize('manage-hr');$d=$this->validate(['deviceId'=>'required|exists:biometric_devices,id','employeeId'=>'required|exists:employees,id','externalEmployeeId'=>'required|string|max:100']);$s->map(BiometricDevice::findOrFail($d['deviceId']),Employee::findOrFail($d['employeeId']),$d['externalEmployeeId']);$this->reset('employeeId','externalEmployeeId');} public function render(){return view('livewire.biometric.devices',['devices'=>BiometricDevice::latest()->get(),'employees'=>Employee::orderBy('name')->get(),'mappings'=>BiometricEmployeeMapping::with(['device','employee'])->latest()->get()]);} }
